import{z as l,x as p,o as t,c as A,q as r,j as E,D as n,d as i,s as o,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"ns-3 与 mininet","description":"","frontmatter":{"title":"ns-3 与 mininet","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/network-simulation.md","filePath":"cs/network-simulation.md","lastUpdated":1791413859000}'),d={name:"cs/network-simulation.md"};function m(c,a,u,h,P,f){const s=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="ns-3-与-mininet" tabindex="-1">ns-3 与 mininet <a class="header-anchor" href="#ns-3-与-mininet" aria-label="Permalink to &quot;ns-3 与 mininet&quot;">​</a></h1><div class="epigraph"><p>ns-3 是离散事件仿真，时间与丢包完全可控；Mininet 用网络命名空间搭真实内核栈的迷你拓扑，保真协议、难保线速。</p><footer>—— 据 ns-3 手册；Lantz et al., Mininet, 2010 整理</footer></div><p><a href="/cs/packet-capture">抓包</a> 在真网上贵。<a href="/cs/packet-capture">上一课</a> 留下「如何复现」。缺口是<strong>仿真 vs 仿真式仿真（emulation）</strong>。本课不把 Reactor 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>incast、AQM、BGP 收敛在生产上难复现。ns-3：事件队列推进虚拟时间，可插传播延迟与错误模型，协议是模型或真实栈移植。Mininet：Linux netns + veth + OVS，跑真 TCP，用 tc 限速，CPU 共享则时间戳假。卫星 RTT 在 ns-3 里设数即可。P4 有 BMv2 仿真点名。</p><p>不要把仿真曲线当 SLA。</p><p><span class="marginnote">Mininet 2010。ns-3 是科研常用。本课不教安装。</span></p><p><span class="marginnote">术语翻译：仿真（simulation）就是用「在程序里建数学模型」的手段来做「推演网络行为」的事；Mininet 那类叫仿真式（emulation）——把真协议栈装进假拓扑里跑，协议是真的，链路和主机是演员。</span></p><h3 id="保真哪一层要先选" tabindex="-1">保真哪一层要先选 <a class="header-anchor" href="#保真哪一层要先选" aria-label="Permalink to &quot;保真哪一层要先选&quot;">​</a></h3><p>ns-3 控时间；Mininet 保真内核栈不保真线速。曲线不是 SLA。随机种子要记。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：数学分析 / ns-3 / Mininet / 试验床。画：问题选工具。与 Clos 拓扑：Mininet 能搭，但脊线速假。</p><p><span class="marginnote">数字实例：想在卫星链路上测 TCP，真实 RTT 数百毫秒，一轮实验要干等十几秒；ns-3 里把传播延迟设成 300 ms，虚拟时间一跳就到位，一秒能扫完几十组参数——不必真发一颗卫星。</span></p>',13)),(t(),E(B,null,{default:n(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NS3%5B%22%E7%A6%BB%E6%95%A3%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20CTRL%5B%22%E5%8F%AF%E6%8E%A7%E6%97%B6%E9%97%B4%22%5D%0A%20%20MINI%5B%22netns%20%E4%BB%BF%E7%9C%9F%22%5D%20--%3E%20REAL%5B%22%E7%9C%9F%E5%86%85%E6%A0%B8%E6%A0%88%22%5D%0A%20%20REAL%20--%3E%20CPU%5B%22%E5%8F%97%E4%B8%BB%E6%9C%BA%20CPU%20%E9%99%90%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"抓包在 Mininet 里方便。iperf 在仿真里量的是模型 \\(C\\)。SDN 控制器可接 Mininet。DNS TTL 可加速测试。不要用仿真证明互联网政策。",-1)),a[5]||(a[5]=e("p",null,"随机种子要记，否则不可复现。",-1)),(t(),E(B,null,{default:n(()=>[o(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20E1%5B%22t%3D10ms%20%E4%BA%8B%E4%BB%B6%EF%BC%9A%E5%8C%85%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20POP%5B%22%E4%BB%8E%E4%BA%8B%E4%BB%B6%E9%98%9F%E5%88%97%E5%BC%B9%E5%87%BA%E6%9C%80%E6%97%A9%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20POP%20--%3E%20ADV%5B%22%E8%99%9A%E6%8B%9F%E6%97%B6%E9%97%B4%E8%B7%B3%E5%88%B0%E8%AF%A5%E4%BA%8B%E4%BB%B6%E6%97%B6%E5%88%BB%22%5D%0A%20%20ADV%20--%3E%20PROC%5B%22%E8%B0%83%E7%94%A8%E5%8D%8F%E8%AE%AE%E6%A8%A1%E5%9E%8B%E5%A4%84%E7%90%86%22%5D%0A%20%20PROC%20--%3E%20NEW%5B%22%E4%BA%A7%E7%94%9F%E6%96%B0%E4%BA%8B%E4%BB%B6%E5%85%A5%E9%98%9F%22%5D%0A%20%20NEW%20--%3E%20POP%0A%20%20PROC%20--%3E%20DONE%5B%22%E9%98%9F%E5%88%97%E4%B8%BA%E7%A9%BA%20%E2%87%92%20%E4%BB%BF%E7%9C%9F%E7%BB%93%E6%9D%9F%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>这张图回答：ns-3 的时间为什么「可控」。它不挂钟计时，而是维护一个按发生时刻排序的事件队列，每次弹出最早事件、把虚拟时间直接跳到那一瞬——中间的空闲无需等待，所以千倍速回放可行。</p><p><span class="marginnote">常见误区：初学者容易把仿真吞吐曲线直接当线上性能承诺。Mininet 大流量下受主机 CPU 调度拖累，时间戳会失真；ns-3 里的容量 \\(C\\) 只是你设的模型参数。曲线用来比较方案优劣，不写进 SLA。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 OMNeT++ 的全部。Reactor/Proactor 是下一课。后课默认：仿真控变量；Mininet 保真栈不保真速率。</p><p>把 1000 台主机仿真在笔记本上会自己成为瓶颈。</p><p>下一课<a href="/cs/reactor-proactor">Reactor / Proactor</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ns-3：虚拟时间，模型清晰。</li><li>Mininet：真协议栈，资源共享。</li><li>选工具看要保真哪一层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：ns-3；Lantz et al., 2010。</li></ul>',8))])}const D=l(d,[["render",m]]);export{T as __pageData,D as default};
